-- Noi Gym / Supabase project exhgtcaczbgdqfozwrvg
-- Correct two Recovery calf-raise source sequences and add reviewed Vietnamese translations.
-- Run the whole file. It is idempotent and refuses to overwrite a changed revision.
begin;
set local lock_timeout = '5s';
lock table public.exercises in share row exclusive mode;
lock table public.exercise_translations in share row exclusive mode;
create temp table _noi_gym_restore_sources on commit drop as select * from jsonb_to_recordset($noi_gym_sources$[{"exercise_id":"4b3f1db2-0c01-40be-953c-f32e214b06d2","source_id":86072620127856,"before_hash":"ba6ff0a64a1abcf3056555e973085f8fd88033ce98f1cd9fffb14c93d00eb3a2","after_hash":"c3088127b769d03e2469a54fd60e69ddf3c9f9dcbe63364dc5f1767d7f0e7dcb","expected_updated_at":"2026-10-14T10:47:02.646442+00:00","steps":["Stand with both feet on the floor and hold a wall for balance.","Raise both heels, then shift your weight onto one leg and lift the other foot.","Hold the top position briefly, then slowly lower the working heel to the floor.","Repeat on the other leg."]},{"exercise_id":"5b494ab8-bc93-4ef0-a5dd-53752fb50853","source_id":267729420447142,"before_hash":"49d29ed8d1052132905f10fbfc219a7a7ee7c127059c99bd238f859fa67ed3eb","after_hash":"53485538bb5c101122700443a01e50f49a5b79f484ca251d0469177280a289aa","expected_updated_at":"2026-10-14T10:47:39.480906+00:00","steps":["Stand with both forefeet on the edge of a step and hold a wall for balance.","Use both legs to raise your heels, then shift your weight onto the working leg and lift the other foot.","Hold the top position briefly, then slowly lower the working heel below the step until you feel a stretch in the calf.","Pause at the end of the range, then repeat on the other leg."]}]$noi_gym_sources$::jsonb) as payload(exercise_id uuid, source_id bigint, before_hash text, after_hash text, expected_updated_at timestamptz, steps jsonb);
create temp table _noi_gym_restore_translations on commit drop as select * from jsonb_to_recordset($noi_gym_translations$[{"exercise_id":"4b3f1db2-0c01-40be-953c-f32e214b06d2","locale":"vi","source_locale":"en","source_hash":"c3088127b769d03e2469a54fd60e69ddf3c9f9dcbe63364dc5f1767d7f0e7dcb","name":"Nâng bắp chân 2A lệch tâm một chân trên sàn","description":"","steps":["Đứng bằng cả hai chân trên sàn và vịn tường để giữ thăng bằng.","Nâng cả hai gót, sau đó chuyển trọng lượng sang một chân và nhấc chân còn lại lên.","Giữ ngắn ở vị trí cao nhất, rồi từ từ hạ gót chân trụ xuống sàn.","Lặp lại với chân kia."],"translation_status":"reviewed","reviewed_at":"2026-10-23T15:50:43.258Z"},{"exercise_id":"5b494ab8-bc93-4ef0-a5dd-53752fb50853","locale":"vi","source_locale":"en","source_hash":"53485538bb5c101122700443a01e50f49a5b79f484ca251d0469177280a289aa","name":"Nâng bắp chân 2C lệch tâm một chân trên bục","description":"","steps":["Đặt phần trước của cả hai bàn chân trên mép bục và vịn tường để giữ thăng bằng.","Dùng cả hai chân nâng gót, sau đó chuyển trọng lượng sang chân trụ và nhấc chân kia lên.","Giữ ngắn ở vị trí cao nhất, rồi từ từ hạ gót chân trụ xuống dưới mặt bục cho đến khi cảm thấy căng bắp chân.","Tạm dừng ở cuối biên độ, sau đó đổi chân."],"translation_status":"reviewed","reviewed_at":"2026-10-23T15:50:43.259Z"}]$noi_gym_translations$::jsonb) as payload(exercise_id uuid, locale text, source_locale text, source_hash text, name text, description text, steps jsonb, translation_status text, reviewed_at timestamptz);
create temp table _noi_gym_restore_before on commit drop as select exercise.* from public.exercises as exercise join _noi_gym_restore_sources as patch on patch.exercise_id = exercise.id;
do $verify_before$
begin
  if (select count(*) from _noi_gym_restore_sources) <> 2 or (select count(*) from _noi_gym_restore_translations) <> 2 or (select count(*) from _noi_gym_restore_before) <> 2 then raise exception 'Unexpected repair scope or wrong Supabase project'; end if;
  if not exists (select 1 from pg_catalog.pg_trigger where tgrelid = 'public.exercises'::regclass and tgname = 'exercises_updated_at' and tgenabled = 'O') then raise exception 'Expected enabled exercise timestamp trigger'; end if;
  if exists (select 1 from public.exercises as exercise join _noi_gym_restore_sources as patch on patch.exercise_id = exercise.id where exercise.source <> 'musclewiki' or exercise.source_id is distinct from patch.source_id or exercise.updated_at is distinct from patch.expected_updated_at or public.exercise_content_hash(exercise.name, exercise.description, exercise.steps) not in (patch.before_hash, patch.after_hash)) then raise exception 'Source revision changed. Do not overwrite; refresh the prepared repair'; end if;
  if exists (select 1 from public.exercise_translations as current join _noi_gym_restore_translations as planned on planned.exercise_id = current.exercise_id and planned.locale = current.locale where current.source_hash is distinct from planned.source_hash or current.source_locale is distinct from planned.source_locale or current.name is distinct from planned.name or current.description is distinct from planned.description or current.steps is distinct from planned.steps or current.translation_status is distinct from planned.translation_status) then raise exception 'Translation changed during review. Refresh the prepared repair'; end if;
end;
$verify_before$;
alter table public.exercises disable trigger exercises_updated_at;
update public.exercises as exercise set steps = patch.steps from _noi_gym_restore_sources as patch where exercise.id = patch.exercise_id and public.exercise_content_hash(exercise.name, exercise.description, exercise.steps) = patch.before_hash;
alter table public.exercises enable trigger exercises_updated_at;
insert into public.exercise_translations (exercise_id, locale, source_locale, source_hash, name, description, steps, translation_status, reviewed_at) select exercise_id, locale, source_locale, source_hash, name, description, steps, translation_status, reviewed_at from _noi_gym_restore_translations on conflict (exercise_id, locale) do nothing;
do $verify_after$
begin
  if exists (select 1 from public.exercises as exercise join _noi_gym_restore_sources as patch on patch.exercise_id = exercise.id join _noi_gym_restore_before as original on original.id = exercise.id where public.exercise_content_hash(exercise.name, exercise.description, exercise.steps) <> patch.after_hash or (to_jsonb(exercise) - 'steps') is distinct from (to_jsonb(original) - 'steps')) then raise exception 'Unexpected exercise field or timestamp change; repair rolled back'; end if;
  if (select count(*) from public.exercise_translations as current join _noi_gym_restore_translations as planned on planned.exercise_id = current.exercise_id and planned.locale = current.locale where current.source_hash = planned.source_hash and current.name = planned.name and current.description = planned.description and current.steps = planned.steps and current.source_locale = planned.source_locale and current.translation_status = 'reviewed' and current.reviewed_at = planned.reviewed_at) <> 2 then raise exception 'Incomplete translation import; transaction rolled back'; end if;
  if not exists (select 1 from pg_catalog.pg_trigger where tgrelid = 'public.exercises'::regclass and tgname = 'exercises_updated_at' and tgenabled = 'O') then raise exception 'Timestamp trigger was not restored; repair rolled back'; end if;
end;
$verify_after$;
commit;
-- Expected immediately after this repair: 1,937 reviewed (1,936 Vietnamese; 1 English).
select count(*) filter (where translation_status = 'reviewed') as reviewed_total, count(*) filter (where translation_status = 'reviewed' and locale = 'vi') as reviewed_vi, count(*) filter (where translation_status = 'reviewed' and locale = 'en') as reviewed_en from public.exercise_translations;
